    /// Normalized PageRank in [0, 1] (max-normalized). Returns 0.0 for unknown nodes.
    pub fn pagerank_score(&self, path: &Path) -> f32 {
        self.pagerank.get(path).copied().unwrap_or(0.0)
    }

    /// 20 iterations), dangling mass redistributed uniformly. Pure-Rust, no deps.
    fn compute_pagerank(&self) -> HashMap<PathBuf, f32> {
        const DAMPING: f32 = 0.85;
        const ITERATIONS: usize = 20;

        // Node universe = every source and every linked target.
        let mut nodes: BTreeSet<&PathBuf> = BTreeSet::new();
        for (src, targets) in &self.adjacency {
            nodes.insert(src);
            for t in targets {
                nodes.insert(t);
            }
        }
        let n = nodes.len();
        if n == 0 {
            return HashMap::new();
        }
        let teleport = (1.0 - DAMPING) / n as f32;
        let base = 1.0 / n as f32;
        let mut rank: HashMap<&PathBuf, f32> = nodes.iter().map(|p| (*p, base)).collect();

        for _ in 0..ITERATIONS {
            let mut next: HashMap<&PathBuf, f32> = nodes.iter().map(|p| (*p, teleport)).collect();
            let mut dangling = 0.0_f32;
            for node in &nodes {
                let r = rank[*node];
                match self.adjacency.get(*node) {
                    Some(targets) if !targets.is_empty() => {
                        let share = DAMPING * r / targets.len() as f32;
                        for t in targets {
                            if let Some(slot) = next.get_mut(t) {
                                *slot += share;
                            }
                        }
                    }
                    _ => dangling += r, // dangling node: redistribute later
                }
            }
            if dangling > 0.0 {
                let spread = DAMPING * dangling / n as f32;
                for slot in next.values_mut() {
                    *slot += spread;
                }
            }
            rank = next;
        }

        // Max-normalize to [0, 1] so the downstream bonus weight is scale-stable.
        let max = rank.values().cloned().fold(0.0_f32, f32::max).max(1e-9);
        rank.into_iter().map(|(p, r)| (p.clone(), r / max)).collect()
    }
```

