// 제안: crates/builder_app/src/planner.rs

/// 전전두엽 — 장기 계획 수립 및 하위 목표 분해
pub struct Planner {
    /// 현재 최상위 목표
    goal: Goal,
    /// 하위 목표 트리 (DAG)
    subgoals: Vec<SubGoal>,
    workflow: WorkflowStateMachine,
}

pub struct Goal {
    pub description: String,           // "192.168.1.0/24 네트워크 침투 테스트"
    pub success_criteria: Vec<String>, // ["최소 3개 호스트 스캔", "발견된 취약점 보고"]
    pub deadline: Option<DateTime<Utc>>,
}

pub struct SubGoal {
    pub id: SubGoalId,
    pub description: String,
    pub parent: Option<SubGoalId>,
    pub status: SubGoalStatus,   // Pending → Active → Completed/Failed
    pub assigned_agent: AgentId, // 어떤 페르소나에게 위임?
    pub phase: WorkflowPhase,
    pub dependencies: Vec<SubGoalId>, // 선행 조건
}

impl Planner {
    /// 최상위 목표를 하위 목표로 분해 (LLM 호출)
    pub async fn decompose_goal(&mut self, llm: &dyn LlmProvider) -> Result<()> {
        // Procedural Memory에서 유사 목표의 과거 절차 검색
        let similar_procedures = self.procedural.find_matching(&self.goal.description);

        // LLM에 목표 + 과거 절차를 주고 분해 요청
        let plan = llm.plan_decomposition(&self.goal, &similar_procedures).await?;
        self.subgoals = plan.subgoals;
        Ok(())
    }

    /// 다음에 실행할 하위 목표 선택
    pub fn next_subgoal(&self) -> Option<&SubGoal> {
        self.subgoals.iter()
            .filter(|sg| sg.status == SubGoalStatus::Pending)
            .filter(|sg| sg.dependencies.iter().all(|dep| self.is_completed(dep)))
            .next()
    }
}
```

