// 제안: crates/builder_knowledge/src/working_memory.rs

pub struct WorkingMemory {
    messages: Vec<ConversationMessage>,
    max_tokens: usize,
    compaction_threshold: f64,   // 0.75
    protected_tail: usize,       // 최근 10개는 컴팩션 대상 제외
}

impl WorkingMemory {
    /// 컨텍스트 초과 시 오래된 메시지를 LLM 요약 → Episodic 저장
    pub async fn compact_if_needed(
        &mut self,
        llm: &dyn LlmProvider,
        episodic: &mut EpisodicMemory,
    ) -> Result<CompactionResult> {
        if self.usage_ratio() < self.compaction_threshold {
            return Ok(CompactionResult::NotNeeded);
        }

        let split = self.messages.len().saturating_sub(self.protected_tail);
        let old = &self.messages[..split];

        let summary = llm.summarize(old).await?;

        episodic.store_episode(Episode {
            source: EpisodeSource::Compaction,
            summary: summary.clone(),
            context: EpisodeContext::from_messages(old),
            timestamp: Utc::now(),
        }).await?;

        self.messages.drain(..split);
        self.messages.insert(0, ConversationMessage::system(
            format!("[이전 대화 요약]\n{}", summary)
        ));

        Ok(CompactionResult::Compacted { removed: split })
    }
}
```

