impl EpisodicMemory {
    pub fn recall_similar(&self, query: &str, ctx: &EpisodeContext, top_k: usize) -> Vec<Episode> {
        let results = self.hybrid_search.search(query, top_k * 3);

        results.into_iter().map(|(note, score)| {
            let mut boost = 0.0;
            if note.context.target == ctx.target { boost += 0.3; }
            if note.context.workflow_phase == ctx.workflow_phase { boost += 0.2; }
            if matches!(note.outcome, EpisodeOutcome::Success { .. }) { boost += 0.1; }
            (note, score + boost)
        })
        .sorted_by(|a, b| b.1.partial_cmp(&a.1).unwrap())
        .take(top_k)
        .inspect(|(ep, _)| self.reinforce(&ep.note.id))
        .map(|(ep, _)| ep)
        .collect()
    }
}
```

