```rust
/// 에피소드가 N회 이상 동일 패턴 → 시맨틱으로 일반화
pub struct SemanticExtractor {
    promotion_threshold: usize, // 3
}

impl SemanticExtractor {
    pub fn extract_from_episodes(&self, episodes: &[Episode]) -> Vec<SemanticNote> {
        // 태그 기반 클러스터링 → threshold 이상 반복 → 일반화된 지식 생성
        let mut clusters: HashMap<String, Vec<&Episode>> = HashMap::new();
        for ep in episodes {
            let key = ep.note.tags.iter().sorted().join("+");
            clusters.entry(key).or_default().push(ep);
        }

        clusters.into_iter()
            .filter(|(_, eps)| eps.len() >= self.promotion_threshold)
            .map(|(key, eps)| SemanticNote {
                title: format!("패턴: {}", key),
                content: Self::synthesize_common_findings(&eps),
                source_episodes: eps.iter().map(|e| e.note.id).collect(),
                confidence: (eps.len() as f64 / 10.0).min(1.0),
            })
            .collect()
    }
}
```

