```rust
impl ProceduralMemory {
    /// 유사 성공 에피소드 시퀀스에서 공통 행동 패턴 → 절차 생성
    pub fn learn_procedure(&mut self, episodes: &[Episode], task_type: &str) -> Option<Procedure> {
        let successful: Vec<_> = episodes.iter()
            .filter(|ep| matches!(ep.outcome, EpisodeOutcome::Success { .. }))
            .collect();

        if successful.len() < 2 { return None; }

        // 공통 행동 시퀀스 추출 (LCS — Longest Common Subsequence)
        let sequences: Vec<Vec<&ActionRecord>> = successful.iter()
            .map(|ep| ep.actions.iter().filter(|a| a.success).collect())
            .collect();

        let common = Self::find_common_sequence(&sequences);
        if common.is_empty() { return None; }

        Some(Procedure {
            steps: common.into_iter().enumerate().map(|(i, a)| ProcedureStep {
                order: i,
                description: a.input_summary.clone(),
                suggested_tools: vec![a.tool.clone()],
                example_command: Some(a.input_summary.clone()),
                expected_output: Some(a.output_summary.clone()),
            }).collect(),
            trigger: ProcedureTrigger {
                keywords: Self::extract_keywords(task_type),
                workflow_phase: Some(successful[0].context.workflow_phase),
                preconditions: vec![],
            },
            stats: ProcedureStats::new(successful.len() as u32),
            note: Note::new_with_type("procedure"),
        })
    }
}
```

