> Nmap 결과 + HTTP 헤더 + Git 노출 + Shodan 정보 → **하나의 상황 모델**

**현재 구현**: 하이브리드 검색이 결과를 병합하지만, **여러 소스의 상황 통합** 개념은 없음

```rust
// 제안: crates/builder_knowledge/src/context_fusion.rs

/// 두정엽 — 여러 정보 소스를 하나의 상황 모델로 융합
pub struct ContextFusion {
    /// 각 소스의 결과
    sources: Vec<InformationSource>,
}

pub struct InformationSource {
    pub name: String,           // "nmap", "http-headers", "git-exposure"
    pub findings: Vec<Finding>,
    pub timestamp: DateTime<Utc>,
    pub confidence: f64,
}

pub struct Finding {
    pub target: String,             // "192.168.1.100"
    pub detail: String,             // "22/tcp SSH OpenSSH 7.4"
    pub severity: Severity,         // Critical, High, Medium, Low, Info
    pub evidence: String,           // raw output snippet
}

/// 여러 소스 → 통합 상황 모델
pub struct SituationModel {
    pub target: String,
    pub attack_surface: Vec<AttackSurfaceEntry>,
    pub vulnerabilities: Vec<Vulnerability>,
    pub relationships: Vec<Relationship>,      // 호스트간 관계
    pub overall_risk: f64,
    pub knowledge_gaps: Vec<String>,           // 아직 모르는 것
}

impl ContextFusion {
    /// 여러 소스를 융합하여 상황 모델 생성
    pub fn fuse(&self) -> SituationModel {
        let mut model = SituationModel::new(&self.primary_target());

        for source in &self.sources {
            for finding in &source.findings {
                match finding.category {
                    FindingCategory::Port | FindingCategory::Service =>
                        model.attack_surface.push(finding.into()),
                    FindingCategory::Vulnerability =>
                        model.vulnerabilities.push(finding.into()),
                    _ => {}
                }
            }
        }

        // 중복 제거 + 충돌 해결 (높은 confidence 우선)
        model.deduplicate_and_resolve();

        // 지식 갭 탐지 — "아직 모르는 것"
        model.knowledge_gaps = self.detect_gaps(&model);

        // 전체 위험도 계산 (Amygdala에 전달)
        model.overall_risk = self.calculate_overall_risk(&model);

        model
    }

    /// 갭 탐지 — 메타인지의 기초
    fn detect_gaps(&self, model: &SituationModel) -> Vec<String> {
        let mut gaps = vec![];

        // 열린 포트는 있지만 서비스 식별 안 된 경우
        for entry in &model.attack_surface {
            if entry.service.is_none() {
                gaps.push(format!("포트 {}: 서비스 미식별", entry.port));
            }
        }

        // 웹 서비스 있지만 디렉토리 스캔 안 한 경우
        if model.has_web_service() && !self.has_source("directory-scan") {
            gaps.push("웹 서비스 발견됨 — 디렉토리 열거 미실시".to_string());
        }

        gaps
    }
}
```

