// 제안: crates/builder_app/src/risk_assessment.rs

/// 편도체 — 위험 즉시 판단
pub struct RiskAssessor {
    /// CVSS 기반 가중치
    weights: RiskWeights,
}

pub struct RiskWeights {
    pub exploitability: f64,  // 0.4 — 얼마나 쉽게 공격?
    pub impact: f64,          // 0.4 — 피해가 얼마나 큰가?
    pub confidence: f64,      // 0.2 — 발견 확실성
}

pub struct RiskScore {
    pub total: f64,           // 0.0 - 10.0
    pub exploitability: f64,
    pub impact: f64,
    pub confidence: f64,
    pub priority: Priority,   // Critical, High, Medium, Low, Info
}

impl RiskAssessor {
    /// 발견된 취약점의 위험도 즉시 계산
    pub fn assess(&self, finding: &Finding) -> RiskScore {
        let exploitability = match finding.detail.as_str() {
            d if d.contains("RCE") || d.contains("Remote Code") => 10.0,
            d if d.contains("SQLi") || d.contains("SQL Injection") => 8.5,
            d if d.contains("XSS") => 6.0,
            d if d.contains("SSRF") => 7.5,
            d if d.contains("Open Redirect") => 3.0,
            d if d.contains("Information Disclosure") => 2.0,
            _ => 5.0,
        };

        let impact = match finding.severity {
            Severity::Critical => 10.0,
            Severity::High => 8.0,
            Severity::Medium => 5.0,
            Severity::Low => 2.0,
            Severity::Info => 0.5,
        };

        let total = self.weights.exploitability * exploitability
                   + self.weights.impact * impact
                   + self.weights.confidence * (finding.confidence * 10.0);

        RiskScore {
            total,
            exploitability,
            impact,
            confidence: finding.confidence,
            priority: Priority::from_score(total),
        }
    }

        findings.sort_by(|a, b| {
            let ra = self.assess(a);
            let rb = self.assess(b);
            rb.total.partial_cmp(&ra.total).unwrap()
        });
    }
}
