// 제안: crates/builder_knowledge/src/execution_optimizer.rs

/// 소뇌 — 실행 순서 최적화 (과거 성공 패턴 학습)
pub struct ExecutionOptimizer {
    /// 기술스택 → 최적 검사 순서 매핑
    patterns: HashMap<String, Vec<OptimizedAction>>,
}

pub struct OptimizedAction {
    pub action: String,           // "check-actuator"
    pub priority: f64,            // 과거 성공률 기반
    pub avg_time_saved_ms: u64,   // 이 순서로 할 때 절약되는 시간
    pub observation_count: u32,   // 관찰 횟수
}

impl ExecutionOptimizer {
    /// 에피소드에서 기술스택별 최적 순서 학습
    pub fn learn_from_episodes(&mut self, episodes: &[Episode]) {
        for ep in episodes {
            if !matches!(ep.outcome, EpisodeOutcome::Success { .. }) { continue; }

            // 기술스택 키 추출 (예: "spring-boot", "php-apache")
            let stack_key = Self::detect_tech_stack(ep);

            // 성공한 행동 순서 기록
            let entry = self.patterns.entry(stack_key).or_default();
            for (i, action) in ep.actions.iter().enumerate() {
                if let Some(opt) = entry.iter_mut().find(|o| o.action == action.tool) {
                    // 이미 있으면 통계 업데이트
                    opt.observation_count += 1;
                    opt.priority = (opt.priority * 0.9) + (1.0 / (i as f64 + 1.0)) * 0.1;
                } else {
                    entry.push(OptimizedAction {
                        action: action.tool.clone(),
                        priority: 1.0 / (i as f64 + 1.0),
                        avg_time_saved_ms: 0,
                        observation_count: 1,
                    });
                }
            }
        }
    }

    /// 현재 기술스택에 맞는 최적 실행 순서 제안
    pub fn suggest_order(&self, tech_stack: &str) -> Vec<String> {
        self.patterns.get(tech_stack)
            .map(|actions| {
                actions.iter()
                    .sorted_by(|a, b| b.priority.partial_cmp(&a.priority).unwrap())
                    .map(|a| a.action.clone())
                    .collect()
            })
            .unwrap_or_default()
    }
}
