```rust
// 제안: crates/builder_app/src/metacognition.rs

/// 메타인지 — "내가 지금 뭘 모르는가?"
pub struct Metacognition {
    /// 현재 태스크에 대한 확신도
    confidence: f64,
    /// 감지된 지식 갭
    knowledge_gaps: Vec<KnowledgeGap>,
    /// 기존 CompletionAdjudicator 확장
    adjudicator: CompletionAdjudicator,
}

pub struct KnowledgeGap {
    pub description: String,  // "포트 8443의 서비스 미식별"
    pub severity: GapSeverity, // Critical, Important, Nice
    pub resolution: GapResolution, // NeedMoreScanning, AskUser, AcceptUncertainty
}

impl Metacognition {
    /// 현재 상황 모델에서 확신도 계산
    pub fn assess_confidence(&mut self, situation: &SituationModel) -> f64 {
        let gap_count = situation.knowledge_gaps.len();
        let finding_count = situation.vulnerabilities.len();
        let surface_coverage = situation.attack_surface_coverage();

        // 확신도 = 커버리지 × (1 - 갭 비율)
        let confidence = surface_coverage * (1.0 - (gap_count as f64 / (gap_count + finding_count + 1) as f64));

        self.confidence = confidence;
        confidence
    }

    /// 확신도가 낮으면 → 추가 조사 제안
    pub fn suggest_next_action(&self) -> MetacognitiveDecision {
        if self.confidence < 0.3 {
            // 확신이 매우 낮음 → 서브에이전트 디스패치
            MetacognitiveDecision::DispatchSubAgent {
                reason: "Need more evidence".to_string(),
                focus: self.most_critical_gap(),
            }
        } else if self.confidence < 0.6 {
            // 중간 → 특정 갭 해결
            MetacognitiveDecision::InvestigateGap {
                gap: self.most_critical_gap(),
            }
        } else {
            // 충분 → 진행
            MetacognitiveDecision::ProceedWithExecution
        }
    }
}
```

