// crates/builder_knowledge/src/context_assembler.rs

pub struct CognitiveContextAssembler {
    episodic: EpisodicMemory,
    semantic: SemanticMemory,
    procedural: ProceduralMemory,
    budget: MemoryBudget,
}

pub struct MemoryBudget {
    pub total_ratio: f64,         // 전체 토큰 중 메모리에 할당할 비율 (0.3)
    pub episodic_weight: f64,     // 0.4
    pub procedural_weight: f64,   // 0.25
}

impl CognitiveContextAssembler {
    pub fn assemble(
        &self,
        query: &str,
        context: &TaskContext,
        available_tokens: usize,
    ) -> AssembledContext {
        let mem_tokens = (available_tokens as f64 * self.budget.total_ratio) as usize;

        // 1. 쿼리 유형 판별 (키워드 기반 — LLM 호출 불필요)
        let query_type = Self::classify_query(query);

        // 2. 유형별 가중치 동적 조정
        let w = match query_type {
            QueryType::ExperienceBased => (0.6, 0.2, 0.2),
            QueryType::KnowledgeBased  => (0.2, 0.6, 0.2),
            QueryType::ProcedureBased  => (0.2, 0.2, 0.6),
            QueryType::General         => (0.4, 0.35, 0.25),
        };

        // 3. 병렬 검색
        let episodes   = self.episodic.recall_similar(query, &context.episode_ctx, 5);
        let knowledge  = self.semantic.query(query, 5);
        let procedures = self.procedural.find_matching(query, context, 3);

        // 4. 토큰 예산 내 조립
        let mut result = AssembledContext::new();
        result.add_section("관련 경험", &episodes,   (mem_tokens as f64 * w.0) as usize);
        result.add_section("관련 지식", &knowledge,  (mem_tokens as f64 * w.1) as usize);
        result.add_section("추천 절차", &procedures, (mem_tokens as f64 * w.2) as usize);
        result
    }

    fn classify_query(query: &str) -> QueryType {
        let q = query.to_lowercase();
        if q.contains("이전에") || q.contains("지난번") || q.contains("했을 때") {
            QueryType::ExperienceBased
        } else if q.contains("어떻게") || q.contains("절차") || q.contains("방법") {
            QueryType::ProcedureBased
        } else if q.contains("뭐야") || q.contains("무엇") || q.contains("CVE") {
            QueryType::KnowledgeBased
        } else {
            QueryType::General
        }
    }
}
